/**
 * 生データ1件を、名前付きのオブジェクトに変換する。
 * @param {Array} row - RAW_PROBLEMS の1要素
 * @returns {{digits:number[], solutionCount:number, difficulty:string, example:(string|null)}}
 */
function toProblem(row) {
  return {
    digits:        row[0].split('').map(Number),
    solutionCount: row[1],
    difficulty:    row[2],
    example:       row[3] || null
  };
}

// モードごとの出題範囲。難易度コードの配列で指定する。
// 画面に出す名前は Normal / Hard / Challenge の3段階。
// Normal は内部の easy と normal をまとめた範囲（合計505問）で、
// 難易度コード（e / n / h / x）は問題データ側の分類なので別物。
const MODES = {
  A: { name: 'Normal',    levels: ['e', 'n'], allowImpossible: false },
  B: { name: 'Hard',          levels: ['h'],      allowImpossible: false },
  C: { name: 'Challenge',     levels: ['h', 'x'], allowImpossible: true  }
};


// ── ハイスコアの保存・読み込み ───────────────────────────────────
/*
 * make10/game.js と同じ方針です。
 * localStorage は環境によって例外を投げます（Cookie を完全にブロックする設定、
 * サードパーティ Cookie が禁止された iframe、一部のアプリ内ブラウザなど）。
 * トップレベルで例外が起きるとファイルの残り全部が実行されず、
 * ボタンを押しても何も起きない真っ白な画面になります。
 * try/catch で包んで、記録が使えないだけの状態に留めます。
 */

/**
 * 指定モードのベスト記録を読み込む。読めない環境では 0 を返す。
 * @param {string} mode - 'A' | 'B' | 'C'
 * @returns {number}
 */
function loadHighScore(mode) {
  try {
    return parseInt(localStorage.getItem('tenpuzzle_hi_' + mode) || '0', 10);
  } catch (e) {
    return 0;  // 読めない環境では記録なしとして扱う
  }
}

/**
 * 指定モードのベスト記録を保存する。保存できない環境では何もせず続行する。
 * 読み込みと分けて try/catch を書く理由は make10 と同じで、
 * Safari のプライベートブラウズなど「読めるが書けない」環境があるためです。
 * @param {string} mode
 * @param {number} value
 */
function saveHighScore(mode, value) {
  try {
    localStorage.setItem('tenpuzzle_hi_' + mode, value);
  } catch (e) {
    /* 保存できなくても続行する（記録は今回のセッション限りになる） */
  }
}


// ── ゲーム状態変数 ───────────────────────────────────────────────
let currentMode    = 'A';   // 選択中のモード
