let questionIndex  = 0;     // 何問目か（0始まり）
let problem        = null;  // 現在の問題（toProblem の戻り値）
let score          = 0;     // 正解数
let hintUsedCount  = 0;     // ヒントを使った回数
let hintUsed       = false; // 今の問題でヒントを使ったか
let tokens         = [];    // 組み立て中の式。{ kind, text, slot } の配列
let locked         = false; // 判定後の待ち時間中は入力を止める


// ── DOM 参照 ────────────────────────────────────────────────────
const screens = {
  top:    document.getElementById('screen-top'),
  game:   document.getElementById('screen-game'),
  result: document.getElementById('screen-result')
};
const digitsRow     = document.getElementById('digitsRow');
const opsGrid       = document.getElementById('opsGrid');
const exprDisplay   = document.getElementById('exprDisplay');
const hintText      = document.getElementById('hintText');
const judgeText     = document.getElementById('judgeText');
const progressValue = document.getElementById('progressValue');
const scoreValue    = document.getElementById('scoreValue');
const btnImpossible = document.getElementById('btn-impossible');
const btnHint       = document.getElementById('btn-hint');


// ── 画面切り替え ────────────────────────────────────────────────
/**
 * 3つの画面のうち1つだけを表示する。
 * @param {'top'|'game'|'result'} name
 */
function showScreen(name) {
  Object.keys(screens).forEach(function (key) {
    screens[key].classList.toggle('active', key === name);
  });
}


// ── トップ画面 ──────────────────────────────────────────────────
/** モードごとのベスト記録をトップ画面に表示する。 */
function renderHighScores() {
  ['A', 'B', 'C'].forEach(function (mode) {
    const hi = loadHighScore(mode);
    const el = document.getElementById('hi-' + mode);
    // 記録がない場合は何も出さない（初回プレイで 0 が並ぶのを避ける）
    el.textContent = hi > 0 ? '★ ' + hi : '';
  });
}


// ── 出題 ────────────────────────────────────────────────────────
/**
 * 配列の中身をランダムに並べ替える（フィッシャー–イェーツ法）。
 * 破壊的に並べ替えるので、呼び出し側でコピーを渡すこと。
 * @param {Array} arr
 * @returns {Array} 並べ替え後の同じ配列
 */
function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
  return arr;
}

/**
 * モードに合う問題を集め、シャッフルして出題キューを作る。
 * @param {string} mode
 */
function buildQueue(mode) {
  const levels = MODES[mode].levels;
  const pool = RAW_PROBLEMS.filter(function (row) {
    return levels.indexOf(row[2]) !== -1;
  });
  queue = shuffle(pool.slice()).slice(0, PROBLEMS_PER_SESSION).map(toProblem);
}

/** 選択されたモードでゲームを開始する。 */
function startGame(mode) {
  currentMode   = mode;
  score         = 0;
  hintUsedCount = 0;
  questionIndex = 0;
  buildQueue(mode);

  // チャレンジモードのときだけ「作れない！」ボタンを出す
  btnImpossible.hidden = !MODES[mode].allowImpossible;

  showScreen('game');
  loadQuestion();
}

/** 次の問題を画面に出す。 */
function loadQuestion() {
  problem  = queue[questionIndex];
  tokens   = [];
  hintUsed = false;
  locked   = false;

  progressValue.textContent = (questionIndex + 1) + ' / ' + queue.length;
  scoreValue.textContent    = score;
  hintText.textContent      = '';
  judgeText.textContent     = '';
  judgeText.className       = 'judge-text';
  btnHint.disabled          = false;

  renderDigits();
  renderExpr();
}

/** 4枚の数字タイルを描き直す。 */
function renderDigits() {
  digitsRow.innerHTML = '';
  problem.digits.forEach(function (value, slot) {
    const btn = document.createElement('button');
    btn.className = 'digit-tile';
    btn.textContent = value;
    btn.style.animationDelay = (slot * 0.05) + 's';
    btn.setAttribute('aria-label', 'Add ' + value + ' to the expression');
    btn.addEventListener('click', function () { pushDigit(value, slot); });
    digitsRow.appendChild(btn);
  });
  updateDigitStates();
}

/** 使用済みの数字タイルを薄くして押せなくする。 */
function updateDigitStates() {
  const usedSlots = tokens
    .filter(function (t) { return t.kind === 'digit'; })
    .map(function (t) { return t.slot; });

  Array.prototype.forEach.call(digitsRow.children, function (btn, slot) {
    const used = usedSlots.indexOf(slot) !== -1;
    btn.classList.toggle('used', used);
    btn.disabled = used;
  });
}

/** 組み立て中の式を表示エリアに描く。 */
function renderExpr() {
  if (tokens.length === 0) {
    exprDisplay.innerHTML = '<span class="expr-placeholder">Tap the digits and symbols</span>';
    return;
  }
  exprDisplay.textContent = tokens.map(function (t) { return t.text; }).join(' ');
}


// ── 入力 ────────────────────────────────────────────────────────
/**
 * 数字タイルを式に追加する。
 * @param {number} value - 数字そのもの
 * @param {number} slot  - 4枚のうち何枚目か（0〜3）。同じタイルの二重使用を防ぐ鍵。
 */
function pushDigit(value, slot) {
  if (locked) return;
  tokens.push({ kind: 'digit', text: String(value), slot: slot });
  clearJudge();
  updateDigitStates();
  renderExpr();
}

/** 演算子・括弧を式に追加する。 */
function pushOp(text) {
  if (locked) return;
  tokens.push({ kind: 'op', text: text, slot: null });
  clearJudge();
  renderExpr();
}

/** ひとつ前の入力を取り消す。 */
function popToken() {
  if (locked) return;
  tokens.pop();
  clearJudge();
  updateDigitStates();
  renderExpr();
}

/** 式をぜんぶ消す。 */
function clearTokens() {
  if (locked) return;
  tokens = [];
  clearJudge();
  updateDigitStates();
  renderExpr();
}

/** 判定メッセージを消す（式をいじったら前回の判定は無効なので）。 */
function clearJudge() {
  judgeText.textContent = '';
  judgeText.className   = 'judge-text';
}

/** ヒント（解の例）を表示する。使うとその問題は加点されない。 */
function showHint() {
  if (locked || hintUsed) return;
  hintUsed = true;
  hintUsedCount++;
  btnHint.disabled = true;

  if (problem.example) {
    hintText.textContent = 'Hint: ' + problem.example;
  } else {
    // impossible 問題には解の例が存在しない
    hintText.textContent = 'Hint: maybe 10 cannot be made from these four…?';
  }
}


// ── 式の評価 ────────────────────────────────────────────────────
/*
 * ★ 判定の考え方 ★
 * アプリ側（TenPuzzleModels.swift）と同じ手順で判定します。
 *   1. 4つの数字を全部使っているか
 *   2. 式として文法的に正しいか（再帰下降パーサーで解析）
 *   3. 計算結果が 10 か（誤差 1e-9 まで許容）
 *
 * 3 で「ぴったり 10 か」ではなく誤差を許すのは、÷ があるからです。
 * たとえば 1÷3×3 は浮動小数点では 0.9999999999999998 になり、
 * === 10 のような厳密比較では正しい式が不正解になってしまいます。
 */

/**
 * 表示用のトークン列を、計算用の文字列トークン列に変換する。
 * 表示は数学記号（− × ÷）、計算は ASCII（- * /）を使う。
 * @returns {string[]}
 */
function toEvalTokens() {
  return tokens.map(function (t) {
    switch (t.text) {
      case '−': return '-';
      case '×': return '*';
      case '÷': return '/';
      default:  return t.text;
    }
  });
}

/**
 * 再帰下降パーサー。四則演算と括弧を解析して数値を返す。
 * 解析できなければ null を返す（＝文法エラー）。
 *
 * 文法:
 *   expr   := term   (('+' | '-') term)*
 *   term   := factor (('*' | '/') factor)*
 *   factor := '(' expr ')' | number
 *
 * ★ 単項マイナス（-3 のような書き方）には対応していません ★
 *   4つの数字と二項演算だけで10を作るゲームなので、必要にならないためです。
 *
 * @param {string[]} list - 計算用トークン列
 * @returns {number|null}
 */
function evaluate(list) {
  let pos = 0;

  function peek() { return pos < list.length ? list[pos] : null; }

  function parseExpr() {
    let left = parseTerm();
    if (left === null) return null;
    while (peek() === '+' || peek() === '-') {
      const op = list[pos++];
      const right = parseTerm();
      if (right === null) return null;
      left = (op === '+') ? left + right : left - right;
    }
    return left;
  }

  function parseTerm() {
    let left = parseFactor();
    if (left === null) return null;
    while (peek() === '*' || peek() === '/') {
      const op = list[pos++];
      const right = parseFactor();
      if (right === null) return null;
      // 0 での除算は Infinity になる。10 にはならないので不正解として流れる。
      left = (op === '*') ? left * right : left / right;
    }
    return left;
  }

  function parseFactor() {
    const token = peek();
    if (token === null) return null;

    if (token === '(') {
      pos++;                       // '(' を読み飛ばす
      const value = parseExpr();
      if (value === null) return null;
      if (peek() !== ')') return null;  // 閉じ括弧がない
      pos++;                       // ')' を読み飛ばす
      return value;
    }

    // 数字（1桁）
    if (/^[0-9]$/.test(token)) {
      pos++;
      return Number(token);
    }

    return null;  // 演算子がいきなり来た等
  }

  const result = parseExpr();
  // 途中で解析が止まって余りが出た場合も文法エラー扱い
  if (result === null || pos !== list.length) return null;
  return result;
}

/**
 * 現在の式を判定する。
 * @returns {'correct'|'wrongAnswer'|'notAllDigitsUsed'|'syntaxError'}
 */
function judgeExpression() {
  const usedDigits = tokens.filter(function (t) { return t.kind === 'digit'; });
  if (usedDigits.length !== 4) return 'notAllDigitsUsed';

  const value = evaluate(toEvalTokens());
  if (value === null) return 'syntaxError';

  return Math.abs(value - 10) < 1e-9 ? 'correct' : 'wrongAnswer';
}


// ── 判定と進行 ──────────────────────────────────────────────────
const JUDGE_MESSAGE = {
  correct:          'Correct! / 正解！',
  wrongAnswer:      'Not 10 / ちがう…',
  notAllDigitsUsed: 'Use all 4 digits / 4つ全部使おう',
  syntaxError:      'Incomplete expression / 式が不完全だよ'
};

/** 「こたえあわせ」ボタンの処理。 */
function onJudge() {
  if (locked) return;

  const result = judgeExpression();

  if (result === 'correct') {
    finishQuestion(true, JUDGE_MESSAGE.correct);
  } else {
    // 不正解でも問題は進めない。何度でも作り直せる。
    showJudgeMessage(JUDGE_MESSAGE[result], false);
  }
}

/** 「作れない！」ボタンの処理（チャレンジモードのみ）。 */
function onDeclareImpossible() {
  if (locked) return;

  if (problem.solutionCount === 0) {
    finishQuestion(true, 'Correct! It was unsolvable / 正解！ 作れない問題でした');
  } else {
    showJudgeMessage('This one is solvable / この問題は作れるよ', false);
  }
}

/**
 * 判定メッセージを表示する。
 * @param {string} message
 * @param {boolean} ok - 正解なら true
 */
function showJudgeMessage(message, ok) {
  judgeText.textContent = message;
  judgeText.className   = 'judge-text ' + (ok ? 'ok' : 'ng');
}

/**
 * 正解して次の問題へ進む。
 * @param {boolean} ok
 * @param {string} message
 */
function finishQuestion(ok, message) {
  locked = true;

  // ヒントを使った問題は加点しない（HINT_PENALTY が true のとき）
  const scored = ok && !(HINT_PENALTY && hintUsed);
  if (scored) score++;

  showJudgeMessage(message + (scored ? '' : ' (hint used)'), ok);
  scoreValue.textContent = score;

  // 少し余韻を置いてから次の問題へ
  setTimeout(function () {
    questionIndex++;
    if (questionIndex >= queue.length) {
      showResult();
    } else {
      loadQuestion();
    }
  }, 900);
}


// ── リザルト ────────────────────────────────────────────────────
/** 結果画面を表示し、必要ならベスト記録を更新する。 */
function showResult() {
  const hi = loadHighScore(currentMode);
  const isNewRecord = score > hi;
  if (isNewRecord) saveHighScore(currentMode, score);

  document.getElementById('resultScore').textContent = score + ' / ' + queue.length;

  const resultHi = document.getElementById('resultHi');
  if (isNewRecord) {
    resultHi.textContent = '🎉 New best! / ベスト更新！';
    resultHi.className   = 'result-hi new-record';
  } else {
    resultHi.textContent = hi > 0 ? 'Best ' + hi : '';
    resultHi.className   = 'result-hi';
  }

  document.getElementById('resultMessage').textContent = resultMessage(score, queue.length);

  const detail = [MODES[currentMode].name + ' mode'];
  if (hintUsedCount > 0) detail.push('Hints used: ' + hintUsedCount);
  document.getElementById('resultDetail').textContent = detail.join(' / ');

  renderHighScores();
  showScreen('result');
}

/**
 * スコアに応じた一言を返す。
 * @param {number} value
 * @param {number} total
 * @returns {string}
 */
function resultMessage(value, total) {
  const rate = total > 0 ? value / total : 0;
  if (rate === 1)    return 'Perfect!';
  if (rate >= 0.7)   return 'Great!';
  if (rate >= 0.4)   return 'Nice work!';
  if (rate > 0)      return 'Keep going!';
  return 'Try again!';
}


// ── 初期化 ──────────────────────────────────────────────────────
/** 演算子・括弧ボタンを生成する。 */
function buildOpButtons() {
  OP_BUTTONS.forEach(function (text) {
    const btn = document.createElement('button');
    btn.className = 'op-btn';
    btn.textContent = text;
    btn.setAttribute('aria-label', 'Add ' + text + ' to the expression');
    btn.addEventListener('click', function () { pushOp(text); });
    opsGrid.appendChild(btn);
  });
}

/** イベントを結び付けて初期表示を作る。 */
function init() {
  buildOpButtons();
  renderHighScores();

  // モード選択ボタン
  Array.prototype.forEach.call(
    document.querySelectorAll('.mode-btn'),
    function (btn) {
      btn.addEventListener('click', function () {
        startGame(btn.dataset.mode);
      });
    }
  );

  document.getElementById('btn-back').addEventListener('click', popToken);
  document.getElementById('btn-clear').addEventListener('click', clearTokens);
  document.getElementById('btn-hint').addEventListener('click', showHint);
  document.getElementById('btn-judge').addEventListener('click', onJudge);
  btnImpossible.addEventListener('click', onDeclareImpossible);

  document.getElementById('btn-home').addEventListener('click', function () {
    showScreen('top');
  });
  document.getElementById('btn-retry').addEventListener('click', function () {
    startGame(currentMode);
  });
  document.getElementById('btn-top').addEventListener('click', function () {
    showScreen('top');
  });

  // キーボード操作（PC 向けのおまけ）
  // 数字キーで該当する数字タイルを、記号キーで演算子を入力できる。
  document.addEventListener('keydown', function (e) {
    if (!screens.game.classList.contains('active')) return;

    if (e.key === 'Enter')     { onJudge();   return; }
    if (e.key === 'Backspace') { popToken();  e.preventDefault(); return; }
    if (e.key === 'Escape')    { clearTokens(); return; }

    if (/^[0-9]$/.test(e.key)) {
      // まだ使っていないタイルのうち、押された数字と一致する最初のものを使う
      const usedSlots = tokens
        .filter(function (t) { return t.kind === 'digit'; })
        .map(function (t) { return t.slot; });
      for (let slot = 0; slot < problem.digits.length; slot++) {
        if (problem.digits[slot] === Number(e.key) && usedSlots.indexOf(slot) === -1) {
          pushDigit(problem.digits[slot], slot);
          return;
        }
      }
      return;
    }

    const keyToOp = { '+': '+', '-': '−', '*': '×', '/': '÷', '(': '(', ')': ')' };
    if (keyToOp[e.key]) pushOp(keyToOp[e.key]);
  });
}

init();
